      const anoC = Number(urlObj.searchParams.get('ano')) || hojeC.getFullYear();
      const ehAnoAtual = (anoC === hojeC.getFullYear());
      const mesC = ehAnoAtual ? (hojeC.getMonth() + 1) : 12;
      out.ano = anoC;
